class StringTokenizer(encoding: String = "utf-8", normalizer: Option[String => String] = None) 
  extends BaseTokenizer[Either[String, Array[Byte]]] {

  private val norm: String => String = normalizer.getOrElse(identity)

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Right(bytes) => new String(bytes, encoding)
      case Left(str) => str
    }
    val normalized = norm(strValue)
    Token(normalized, TokenType.STRING)
  }

  // Overload for convenience if needed, but BaseTokenizer requires the generic type
  def tokenizeString(s: String): Token = tokenize(Left(s))
  def tokenizeBytes(b: Array[Byte]): Token = tokenize(Right(b))
